new RelicDef{id="haste",name="Chuông Gió Trúc Lâm",icon="◇",desc="Tốc đánh +16%, chạy +12%; di chuyển liên tục 3 giây tạo gió đẩy lệch đạn chậm.",atlas=22,source="pedestal",boss="",lore="Năm ống trúc treo dưới chỉ đỏ. Gió đi qua không lấy một nốt nào, chỉ trao thêm bước chân.",origin="Vượt rìa bắc Cội Đa vào Biên Viễn, nghe chuông trúc ngoài sương."},
new RelicDef{id="spirit",name="Ngọc Tịnh Tâm",icon="◇",desc="MP tối đa +40, chí mạng +8%; đòn chí mạng hồi 3 MP.",atlas=23,source="pedestal",boss="",lore="Minh châu nghỉ giữa tám cánh sen bạc. Mặt nước lặng để người mang nghe được tiếng thở của mình.",origin="Gò sen yên tĩnh phía nam Đầm Sen, ba gương giữ một vệt sáng."},
new RelicDef{id="wildfire",name="Lồng Đèn Lưu Hỏa",icon="◇",desc="Mọi đòn gắn Thiêu Đốt. Địch đang cháy chết: nổ lửa 140% sát thương trong 160 px, lan lửa.",atlas=24,source="pedestal",boss="",lore="Hỏa hồ ly vẽ trên giấy đèn vẫn vờn một đốm than. Ngọn lửa truyền đi cả sức nóng lẫn ký ức.",origin="Rìa tây Rừng Trúc, chiếc đèn cũ giấu sau tầng lá dày."},
new RelicDef{id="dashshock",name="Trống Đồng Lôi Vũ",icon="◇",desc="Lướt giáng sấm tại điểm đầu và cuối: 180% sát thương vùng, tê liệt 0,8 giây.",atlas=25,source="pedestal",boss="",lore="Mười bốn cánh sao Đông Sơn gọi mưa và sấm. Một nhịp trống giữ hai dấu chân giữa đường lướt.",origin="Đàn đá giữa lòng Đầm Sen, bốn màu còn nhớ nhịp sấm."},
new RelicDef{id="split",name="Nỏ Liên Châu Cổ",icon="◇",desc="Đòn bắn thường và chiêu dạng đạn thêm 1 tia phụ 85% sát thương. Đòn cận chiến thêm kiếm khí.",atlas=26,source="pedestal",boss="",lore="Nỏ sơn son đặt ba mũi tên cạnh lẫy đồng. Người thợ xưa để lại một đường bắn cho lời hẹn chưa trúng đích.",origin="Góc tây bắc Rừng Trúc, ba trụ cổ che khuất cánh nỏ."},
new RelicDef{id="pierce",name="Mũi Giáo Xuyên Vân",icon="◇",desc="Mọi đạn xuyên thêm 3 mục tiêu; mỗi lần xuyên tăng 12% sát thương cho lần trúng tiếp.",atlas=27,source="pedestal",boss="",lore="Mũi giáo ngọc khắc rãnh mây. Càng đi xa qua sương, nó càng nhớ rõ hướng ban đầu.",origin="Đèo cực nam Thung Lũng Đèn, mũi giáo chờ sau đá tái sinh."},
new RelicDef{id="vampire",name="Chén Ngọc Huyết Sen",icon="◇",desc="Hút 4% sát thương; hạ địch hồi 6 HP, gấp đôi khi địch cháy hoặc chảy máu.",atlas=28,source="pedestal",boss="",lore="Chén sen hồng không giữ máu người vô tội. Nó trả hơi ấm từ những lời nguyền đã được giải phóng.",origin="Vùng bùn phía tây Phế Tích, chén sen đợi lời thề bằng máu."},
new RelicDef{id="chain",name="Hồ Lô Lôi Điện",icon="◇",desc="35% cơ hội phóng Lôi Xích qua 3 địch trong 220 px, mỗi nhịp 65% sát thương.",atlas=29,source="pedestal",boss="",lore="Hồ lô đồng tím nhốt một tiếng sấm chưa chịu ngủ. Dây vàng giữ miệng bình, không giữ hết tia điện.",origin="Vách đông nối Thác Ngọc với Phế Tích, tiếng sấm ngủ trong bốn chuông."},
new RelicDef{id="cooling",name="Lõi Băng Thiên Cơ",icon="◇",desc="Hồi Q/E/R giảm 22%; mỗi chiêu tỏa hàn khí làm chậm địch 30%.",atlas=30,source="pedestal",boss="",lore="Bốn góc máy mở ra trước lõi băng vĩnh cửu. Cỗ máy biết nghỉ một nhịp trước khi tiếp tục làm việc.",origin="Hầm lạnh phía nam Phế Tích Thiên Cơ, vòng đạn canh lõi băng."},
new RelicDef{id="dom",name="Vòng Cổ Linh Thú Của Đốm",icon="◇",desc="Đốm hút đồ 380 px, chỉ bệ/rương trong 650 px, hồi 2 HP/s; mỗi 4 giây tấn công 150% sát thương.",atlas=31,source="pedestal",boss="",lore="Chuông vàng khắc dấu chân cáo rung rất khẽ. Chiếc vòng nhớ bàn tay người bạn đầu tiên, dù người ấy đã quên tên mình.",origin="Đồng cỏ cực nam Thung Lũng Đèn, dấu chân cáo quanh rễ khô."},
new RelicDef{id="kimquy",name="Móng Kim Quy",icon="◇",desc="Chịu đòn: khiên 35 + 15% Máu tối đa, phản kích 3 tên xuyên gây 240% sát thương về kẻ tấn công. Hồi 10 giây.",atlas=0,source="boss",boss="Huyền Quy Cổ Thạch",lore="Mảnh móng vàng giữ lời hẹn của Kim Quy với người bảo vệ bờ cõi. Ngọc ở gốc móng vẫn nhớ hướng mũi tên đầu tiên.",origin="Bờ đông sông Thác Ngọc, ba tinh thể giữ một mai rùa ngủ."},
new RelicDef{id="giong",name="Đốt Tre Phù Đổng",icon="◇",desc="Mỗi đòn thứ 4 dựng hàng tre dài 340 px gây 220% sát thương, hất tung 0,6 giây.",atlas=1,source="boss",boss="Trúc Vệ · Kẻ Canh Gió",lore="Tre Phù Đổng từng thay gươm sắt khi lửa chưa tắt trên đồng. Ba lá đồng vẫn bay theo người không chịu lùi.",origin="Thánh vật rơi từ Trúc Vệ · Kẻ Canh Gió"},
new RelicDef{id="thachsan",name="Đàn Thần Thạch Sanh",icon="◇",desc="E: Khúc Nhạc Giải Binh bán kính 280 px, mê hoặc quái 2,2 giây; Boss giảm 30% tốc độ và sát thương trong 2 giây. Hồi 9 giây.",atlas=2,source="boss",boss="Hồ Tinh",lore="Tiếng đàn Thạch Sanh khiến binh đao ngừng giữa một nhịp thở. Ba dây sao chỉ rung khi người cầm còn muốn nghe đối phương.",origin="Thánh vật rơi từ Hồ Tinh"},
new RelicDef{id="sontinh",name="Ấn Núi Tản Viên",icon="◇",desc="Mỗi 6 giây nhận thạch giáp giảm 25% sát thương của đòn kế. Khi trúng cận chiến hoặc dùng Q, dựng 3 cột đá gây 190% sát thương và đẩy mạnh.",atlas=3,source="boss",boss="Cửu Khúc Xà",lore="Ba đỉnh núi trên ấn đã đứng qua nhiều mùa nước lớn. Mây quấn quanh đá như lời thề giữ một mái nhà.",origin="Thánh vật rơi từ Cửu Khúc Xà"},
new RelicDef{id="thuytinh",name="Giọt Nước Thủy Phủ",icon="◇",desc="Q tạo xoáy nước 145 px trong 4,5 giây, hút địch và gắn Ẩm Ướt: nhận thêm 30% sát thương Lôi/Băng, dẫn điện dây chuyền.",atlas=4,source="boss",boss="Hà Bá",lore="Giọt nước giữ bóng thủy giao và một dòng sông chưa được trả tên. Không bàn tay nào nắm nước mãi được.",origin="Thánh vật rơi từ Hà Bá"},
new RelicDef{id="cuoi",name="Lá Đa Chú Cuội",icon="◇",desc="Chặn sát thương chí tử, hồi 60% Máu và 100% MP, xóa trạng thái xấu, đẩy địch, bất tử 3 giây. Hồi 180 giây chiến đấu.",atlas=5,source="boss",boss="Mộc Quỷ",lore="Lá đa giữ ánh trăng từ đêm Cuội níu rễ cây. Giọt sương trên cuống không rơi xuống đất, như một lời chưa muốn buông.",origin="Thánh vật rơi từ Mộc Quỷ"},
new RelicDef{id="ankh",name="Chìa Khóa Sinh Mệnh Ankh",icon="◇",desc="Hạ địch đang chậm, đóng băng, trói, choáng hoặc cháy: hút cầu sinh mệnh hồi 5% Máu tối đa, tăng 15% sát thương trong 4 giây.",atlas=6,source="boss",boss="Thần Trùng",lore="Lapis Lazuli giữ sắc trời bên sông Nile. Chiếc khóa của sự sống không mở mộ; nó mở một nhịp thở còn có thể trở về.",origin="Thánh vật rơi từ Thần Trùng"},
new RelicDef{id="hermes",name="Đôi Hài Cánh Hermes",icon="◇",desc="Chạy +18%; mỗi lướt có thêm 1 lần lướt miễn phí trong 1,5 giây. Kỹ năng trúng đích giảm 0,4 giây hồi lướt.",atlas=7,source="boss",boss="Thiết Điểu",lore="Đôi cánh ở mắt cá chân nhớ đường của những người đưa tin. Người mang hài được thêm một bước để giữ lời hẹn.",origin="Thánh vật rơi từ Thiết Điểu"},
new RelicDef{id="ariadne",name="Cuộn Chỉ Vàng Ariadne",icon="◇",desc="Lướt để lại chỉ 4 giây: địch chạm chịu sát thương chuẩn mỗi giây, giảm 25% Giáp và chậm 50%. Dưới 35% Máu: lướt miễn thương ít nhất 0,5 giây.",atlas=8,source="boss",boss="Kẻ Dệt Sương",lore="Sợi chỉ Ariadne đã dẫn một người ra khỏi mê cung. Nó giữ đường về, không chọn thay người bước.",origin="Thánh vật rơi từ Kẻ Dệt Sương"},
new RelicDef{id="mjolnir",name="Ấn Búa Sấm Mjölnir",icon="◇",desc="Mỗi đòn thứ 5 gọi búa nổ trong 120 px và sét lan qua 4 mục tiêu; 130% sát thương mỗi nhịp.",atlas=9,source="boss",boss="Cự Nhân Sắt",lore="Runes trên thép Uru gọi sấm về cán búa. Tiếng sét vẫn vang dù bàn tay người thợ đã thành tro.",origin="Giữa Phế Tích Thiên Cơ, ba dây điện chờ đánh thức khung giáp."},
new RelicDef{id="wukong",name="Sợi Lông Hầu Vương",icon="◇",desc="E hoặc lướt gọi 2 Hầu Ảnh có máu riêng, tự chiến đấu 4 giây, mỗi đòn 75% sát thương. Hồi 8 giây.",atlas=10,source="boss",boss="Hầu Ảnh Sơn Lâm",lore="Một sợi lông của Hầu Vương mang bóng mây Cân Đẩu Vân. Hai bóng nhỏ cùng cầm gậy, cùng cười trước lúc tan thành khói vàng.",origin="Sâu trong Rừng Trúc, chuông bốn hướng ôm lấy tượng khỉ đá."},
new RelicDef{id="phoenix",name="Lông Vũ Phượng Hoàng Lửa",icon="◇",desc="R bung cánh phượng 6 giây, hồi 18% Máu tối đa, hào quang lửa 240 px và tăng 25% mọi sát thương.",atlas=11,source="boss",boss="Hỏa Điểu Tro Tàn",lore="Lông đuôi phượng giữ hơi nóng sau mỗi lần tro tàn. Cánh lửa mở vì sự sống tiếp tục, không vì quá khứ bị xóa.",origin="Đỉnh Đồi Tro, tổ lạnh đợi bốn đài lửa và bốn người canh."},
new RelicDef{id="chudong",name="Trượng Nón Chử Đồng Tử",icon="◇",desc="Mở rương, chạm đền hoặc tương tác môi trường: Lâu Đài Ảo Ảnh 5 giây, hồi 15% Máu +20 MP, Giáp +20%.",atlas=12,source="pedestal",boss="",lore="Gậy và nón của Chử Đồng Tử từng dựng một nơi nương náu giữa bãi cát. Ba giọt sương còn xoay quanh mái nhà ấy.",origin="Bãi cát cuối bờ đông Đầm Sen, nơi chiếc nón từng che một mái nhà."},
new RelicDef{id="tam",name="Chiếc Hài Gấm Cô Tấm",icon="◇",desc="Lướt để lại quả thị ảo ảnh thu hút quái thường trong 2,5 giây; chạy +25%.",atlas=13,source="pedestal",boss="",lore="Chiếc hài gấm tựa trên quả thị thơm. Người bước qua nỗi oan vẫn để lại một lối sống mềm hơn cơn giận.",origin="Dưới bóng đa phía bắc, hương thị lạc giữa những gốc cổ thụ."},
new RelicDef{id="antiem",name="Hạt Dưa Đỏ Mai An Tiêm",icon="◇",desc="Mỗi 6 mạng mọc một Quả Dưa Linh Thảo tại xác. Chạy qua ăn: +25 HP, +20 MP, tốc đánh +15% trong 5 giây.",atlas=14,source="pedestal",boss="",lore="Hạt dưa Mai An Tiêm bén rễ trên đảo vắng. Sự sống trở lại từ một điều nhỏ được giữ qua ngày đói.",origin="Cồn đất phía đông Thác Ngọc, hạt đỏ chờ người vượt nước."},
new RelicDef{id="traucau",name="Lá Trầu Phượng Cánh",icon="◇",desc="Bình Máu hồi thêm 30%, tạo khiên bằng 30% Máu tối đa; 35% cơ hội không tiêu hao bình.",atlas=15,source="pedestal",boss="",lore="Lá trầu, quả cau và đá vôi giữ câu chuyện về tình thân không kịp nói. Ba màu kết thành một cánh phượng ấm.",origin="Mép tây nam Thung Lũng Đèn, ba thân cây cùng giữ một lời hẹn."},
new RelicDef{id="aegis",name="Khiên Thần Aegis",icon="◇",desc="Sau 7 giây không chịu đòn hoặc dùng Q/E: nhận Khiên Aegis. Khi vỡ: hóa đá địch trong 160 px suốt 1,2 giây.",atlas=16,source="pedestal",boss="",lore="Đầu Medusa mở mắt ở mặt khiên, giữ khoảnh khắc trước khi lưỡi kiếm chạm da. Cái nhìn bằng ngọc dừng bước người còn muốn đánh.",origin="Điện thờ nơi Phế Tích Thiên Cơ chạm biên giới đông nam."},
new RelicDef{id="aladdin",name="Đèn Thần Aladdin",icon="◇",desc="Mỗi 80 MP tiêu thụ: hoàn 30 MP, gọi Thần Đèn bắn tia xuyên 280% sát thương.",atlas=17,source="pedestal",boss="",lore="Làn khói lam trong đèn không hứa điều ước miễn phí. Nó đợi linh lực đã bỏ ra trở thành một tia sáng có ích.",origin="Bờ đông đầu nguồn Thác Ngọc, ngọn đèn ngủ giữa đá lạnh."},
new RelicDef{id="jack",name="Hạt Đậu Thần Khổng Lồ",icon="◇",desc="Mỗi 6 giây giao chiến: dây leo trói nhóm địch đông nhất trong 2,2 giây, rút máu chuyển cho chủ.",atlas=18,source="pedestal",boss="",lore="Hạt đậu của Jack nứt vỏ dưới một đám mây nhỏ. Rễ không hỏi người đứng trên đất có tin vào bầu trời hay không.",origin="Rìa bắc Rừng Trúc, dây leo chạm mây trước lúc bình minh."},
