a đạn.",passive="Di chuyển nhanh hơn 12%."},new ElementDef{id="earth",name="Thổ",title="Nham Giáp",color="#e4b074",accent="#ffe1aa",icon="◆",q="Địa Liệt Nham Trụ",e="Rung Chấn Nham Giáp",r="Người Khổng Lồ Đất",desc="Trụ đá, chấn động, giáp và khiên bền vững.",passive="Nhận ít hơn 12% sát thương."},new ElementDef{id="fire",name="Hỏa",title="Xích Diệm",color="#ff9869",accent="#fff0b2",icon="♨",q="Phun Lửa",e="Thiên Thạch Hỏa Ngục",r="Cầu Lửa Khổng Lồ",desc="Hỏa long, vòng lửa và thiên thạch thiêu đốt.",passive="Đòn đánh để lại thiêu đốt."},new ElementDef{id="ice",name="Băng",title="Băng Tinh",color="#8bddff",accent="#eaffff",icon="❄",q="Núi Băng Vĩnh Tỏa",e="Bão Tuyết",r="Băng Hà Thiên Táng",desc="Băng châm xuyên, làm chậm và đóng băng.",passive="Đòn đánh làm chậm; chiêu có thể đóng băng."},new ElementDef{id="nature",name="Mộc",title="Linh Mộc",color="#a9e898",accent="#f6e7b0",icon="❧",q="Rễ Gai Trói Chân",e="Dây Leo Khổng Lồ",r="Thức Tỉnh Rừng Già",desc="Dây leo trói, hạt độc và hồi phục.",passive="Hạt mộc gây độc và hồi nhẹ khi hạ quái."},new ElementDef{id="light",name="Quang",title="Thái Dương",color="#ffe5a5",accent="#ffffff",icon="☀",q="Tốc Độ Ánh Sáng",e="Tia Năng Lượng Mặt Trời",r="Thái Dương Diệt Ảnh",desc="Tia sáng xuyên, phản đạn và pháo thái dương.",passive="Đạn thường xuyên ba mục tiêu."}}};} } }
